mapper.select:
SELECT department.id AS id, department.code AS code, department.name AS name, department.is_deleted AS is_deleted, ( SELECT COUNT(*) FROM users user_account WHERE user_account.department_id = department.id AND user_account.is_deleted = FALSE ) AS active_user_count, department.created_at AS created_at, department.updated_at AS updated_at FROM departments department WHERE department.company_id = #{companyId}
AND department.is_deleted = FALSE
ORDER BY department.code ASC, department.id ASC

SELECT EXISTS(
    SELECT 1
    FROM departments department
    WHERE department.company_id = #{companyId}
        AND department.code = #{code}
)

mapper.update:
UPDATE departments
SET name = #{name},
    updated_by = #{updatedBy}
WHERE id = #{departmentId}
    AND company_id = #{companyId}
    AND is_deleted = FALSE

UPDATE departments
SET is_deleted = TRUE,
    updated_by = #{updatedBy}
WHERE id = #{departmentId}
    AND company_id = #{companyId}
    AND is_deleted = FALSE
